def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    v3 = vars["v3"]
    total_intangible_assets = v1 + v2 + v3

    return {
        "value": total_intangible_assets,
        "trace": {
            "v1_developed_technology_and_know_how": v1,
            "v2_customer_relationship": v2,
            "v3_trade_name": v3,
            "total_intangible_assets": total_intangible_assets,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
